    public static Step? Find(uint questId)
    {
        foreach (var step in Steps)
        {
            if (step.QuestId == questId)
            {
                return step;
            }
        }

        return null;
    }

    public static Step? Next(uint questId) =>
        Find(questId) is { NextQuestId: { } next } ? Find(next) : null;
}
